1	/* sno_util.plsw -- Layer 1: shared utilities
2	 * String helpers, I/O, character classification.
3	 * No dependencies on other SNOBOL4 modules.
4	 */
5	%DEFINE LIBRARY;
6	%INCLUDE descr;
7	%INCLUDE heap;
8	%INCLUDE am;
9	%INCLUDE pat;
10	%INCLUDE snoglob;
11	
12	/* ---- SB overflow guard ----
13	 * SB has no GC or compaction (see issue #12). SB_ABORT prints a
14	 * diagnostic and sets SB_OVERFLOW so the executor loop can stop
15	 * cleanly instead of silently corrupting adjacent globals. */
16	
17	SB_ABORT: PROC;
18	    IF (SB_OVERFLOW != 0) THEN RETURN;
19	    SB_OVERFLOW = 1;
20	    CALL UART_PUTS(ADDR(SB_OVF_MSG));
21	    CALL PUT_DEC(SBPOS);
22	    CALL UART_PUTCHAR(10);
23	END;
24	
25	SB_CHECK: PROC(N INT);
26	    IF (SBPOS + N >= SB_LIMIT) THEN
27	        CALL SB_ABORT;
28	END;
29	
30	/* ---- Source/Input readers ---- */
31	
32	READ_SRC: PROC;
33	    DCL P INT;
34	    DCL RP PTR;
35	    DCL CH INT;
36	    P = 0;
37	    RP = SRC_LOAD_ADDR;
38	    CH = RP->DTAG;
39	    DO WHILE (CH != 0 AND P < SRC_LIMIT);
40	        SRC(P) = CH;
41	        P = P + 1;
42	        RP = SRC_LOAD_ADDR + P;
43	        CH = RP->DTAG;
44	    END;
45	    SRC(P) = 0;
46	    /* Detect source overrun: if more input remains after the buffer
47	     * filled, halt with a diagnostic rather than silently truncating
48	     * a program (issue #14). */
49	    IF (CH != 0) THEN DO;
50	        CALL UART_PUTS(ADDR(SRC_OVF_MSG));
51	        CALL PUT_DEC(P);
52	        CALL UART_PUTCHAR(10);
53	        SB_OVERFLOW = 1;
54	    END;
55	END;
56	
57	READ_INPUT: PROC RETURNS(INT);
58	    DCL OFF INT;
59	    DCL RP PTR;
60	    DCL DP PTR;
61	    DCL CH INT;
62	    DCL DONE INT;
63	
64	    /* TTY mode: read a line live from UART RX, with local echo and
65	     * a tiny line editor (backspace). Ctrl-D (0x04) on an empty line
66	     * signals EOF. CR (0x0D) and LF (0x0A) both terminate a line. */
67	    IF (INP_TTY = 1) THEN DO;
68	        OFF = SBPOS;
69	        DONE = 0;
70	        DO WHILE (DONE = 0);
71	            CH = UART_GETCHAR();
72	            IF (CH = 4) THEN DO;
73	                /* Ctrl-D: EOF if line empty, else ignore */
74	                IF (SBPOS = OFF) THEN RETURN(0 - 1);
75	            END;
76	            ELSE IF (CH = 13 OR CH = 10) THEN DO;
77	                CALL UART_PUTCHAR(10);
78	                DONE = 1;
79	            END;
80	            ELSE IF (CH = 8 OR CH = 127) THEN DO;
81	                IF (SBPOS > OFF) THEN DO;
82	                    SBPOS = SBPOS - 1;
83	                    CALL UART_PUTCHAR(8);
84	                    CALL UART_PUTCHAR(32);
85	                    CALL UART_PUTCHAR(8);
86	                END;
87	            END;
88	            ELSE DO;
89	                /* Auto-uppercase ASCII a-z so keyword matching is
90	                 * case-insensitive (classic SNOBOL4 convention). */
91	                IF (CH >= 97) THEN IF (CH <= 122) THEN CH = CH - 32;
92	                DP = ADDR(SB) + SBPOS;
93	                DP->DTAG = CH;
94	                SBPOS = SBPOS + 1;
95	                CALL UART_PUTCHAR(CH);
96	            END;
97	        END;
98	        DP = ADDR(SB) + SBPOS;
99	        DP->DTAG = 0;
100	        SBPOS = SBPOS + 1;
101	        RETURN(OFF);
102	    END;
103	
104	    /* Batch mode: read from data file pre-loaded at INP_LOAD_ADDR. */
105	    RP = INP_LOAD_ADDR + INP_POS;
106	    CH = RP->DTAG;
107	    IF (CH = 0) THEN RETURN(0 - 1);
108	    OFF = SBPOS;
109	    DO WHILE (CH != 10 AND CH != 0);
110	        IF (CH >= 97) THEN IF (CH <= 122) THEN CH = CH - 32;
111	        DP = ADDR(SB) + SBPOS;
112	        DP->DTAG = CH;
113	        SBPOS = SBPOS + 1;
114	        INP_POS = INP_POS + 1;
115	        RP = INP_LOAD_ADDR + INP_POS;
116	        CH = RP->DTAG;
117	    END;
118	    DP = ADDR(SB) + SBPOS;
119	    DP->DTAG = 0;
120	    SBPOS = SBPOS + 1;
121	    IF (CH = 10) THEN
122	        INP_POS = INP_POS + 1;
123	    RETURN(OFF);
124	END;
125	
126	READ_RAW_INPUT: PROC RETURNS(INT);
127	    DCL OFF INT;
128	    DCL RP PTR;
129	    DCL DP PTR;
130	    DCL CH INT;
131	    DCL DONE INT;
132	
133	    /* TTY mode: read a line live, case-preserving */
134	    IF (INP_TTY = 1) THEN DO;
135	        OFF = SBPOS;
136	        DONE = 0;
137	        DO WHILE (DONE = 0);
138	            CH = UART_GETCHAR();
139	            IF (CH = 4) THEN DO;
140	                IF (SBPOS = OFF) THEN RETURN(0 - 1);
141	            END;
142	            ELSE IF (CH = 13 OR CH = 10) THEN DO;
143	                CALL UART_PUTCHAR(10);
144	                DONE = 1;
145	            END;
146	            ELSE IF (CH = 8 OR CH = 127) THEN DO;
147	                IF (SBPOS > OFF) THEN DO;
148	                    SBPOS = SBPOS - 1;
149	                    CALL UART_PUTCHAR(8);
150	                    CALL UART_PUTCHAR(32);
151	                    CALL UART_PUTCHAR(8);
152	                END;
153	            END;
154	            ELSE DO;
155	                /* No uppercasing -- preserve case */
156	                DP = ADDR(SB) + SBPOS;
157	                DP->DTAG = CH;
158	                SBPOS = SBPOS + 1;
159	                CALL UART_PUTCHAR(CH);
160	            END;
161	        END;
162	        DP = ADDR(SB) + SBPOS;
163	        DP->DTAG = 0;
164	        SBPOS = SBPOS + 1;
165	        RETURN(OFF);
166	    END;
167	
168	    /* Batch mode: read from data file, case-preserving */
169	    RP = INP_LOAD_ADDR + INP_POS;
170	    CH = RP->DTAG;
171	    IF (CH = 0) THEN RETURN(0 - 1);
172	    OFF = SBPOS;
173	    DO WHILE (CH != 10 AND CH != 0);
174	        /* No uppercasing -- preserve case */
175	        DP = ADDR(SB) + SBPOS;
176	        DP->DTAG = CH;
177	        SBPOS = SBPOS + 1;
178	        INP_POS = INP_POS + 1;
179	        RP = INP_LOAD_ADDR + INP_POS;
180	        CH = RP->DTAG;
181	    END;
182	    DP = ADDR(SB) + SBPOS;
183	    DP->DTAG = 0;
184	    SBPOS = SBPOS + 1;
185	    IF (CH = 10) THEN
186	        INP_POS = INP_POS + 1;
187	    RETURN(OFF);
188	END;
189	
190	/* Parse null-terminated decimal digits at SB+OFF into an integer.
191	 * Optional leading '-' for negative. Non-digit chars terminate parsing.
192	 * Empty or non-numeric input returns 0 (SNOBOL4 coercion convention). */
193	PARSE_INT: PROC(OFF INT) RETURNS(INT);
194	    DCL P PTR;
195	    DCL C INT;
196	    DCL N INT;
197	    DCL I INT;
198	    DCL NEG INT;
199	    N = 0;
200	    I = 0;
201	    NEG = 0;
202	    P = ADDR(SB) + OFF;
203	    C = P->DTAG;
204	    IF (C = 45) THEN DO;
205	        NEG = 1;
206	        I = 1;
207	        P = ADDR(SB) + OFF + I;
208	        C = P->DTAG;
209	    END;
210	    DO WHILE (C >= 48 AND C <= 57);
211	        N = N * 10 + C - 48;
212	        I = I + 1;
213	        P = ADDR(SB) + OFF + I;
214	        C = P->DTAG;
215	    END;
216	    IF (NEG = 1) THEN N = 0 - N;
217	    RETURN(N);
218	END;
219	
220	/* ---- String helpers ---- */
221	
222	SLEN: PROC(S PTR) RETURNS(INT);
223	    DCL I INT;
224	    DCL P PTR;
225	    I = 0;
226	    P = S;
227	    DO WHILE (P->DTAG != 0);
228	        I = I + 1;
229	        P = S + I;
230	    END;
231	    RETURN(I);
232	END;
233	
234	SCEQ: PROC(A PTR, B PTR) RETURNS(INT);
235	    DCL I INT;
236	    DCL AP PTR;
237	    DCL BP PTR;
238	    DCL CA INT;
239	    DCL CB INT;
240	    I = 0;
241	    DO WHILE (1 = 1);
242	        AP = A + I;
243	        BP = B + I;
244	        CA = AP->DTAG;
245	        CB = BP->DTAG;
246	        IF (CA != CB) THEN RETURN(0);
247	        IF (CA = 0) THEN RETURN(1);
248	        I = I + 1;
249	    END;
250	    RETURN(1);
251	END;
252	
253	IN_CLASS: PROC(C INT, CLASS PTR) RETURNS(INT);
254	    DCL I INT;
255	    DCL P PTR;
256	    DCL CH INT;
257	    I = 0;
258	    P = CLASS;
259	    CH = P->DTAG;
260	    DO WHILE (CH != 0);
261	        IF (CH = C) THEN RETURN(1);
262	        I = I + 1;
263	        P = CLASS + I;
264	        CH = P->DTAG;
265	    END;
266	    RETURN(0);
267	END;
268	
269	IS_END: PROC RETURNS(INT);
270	    IF (TB(0) = 69) THEN IF (TB(1) = 78) THEN IF (TB(2) = 68) THEN
271	        IF (TB(3) = 0) THEN RETURN(1);
272	    RETURN(0);
273	END;
274	
275	IS_DUMP: PROC RETURNS(INT);
276	    IF (TB(0) = 68) THEN IF (TB(1) = 85) THEN IF (TB(2) = 77) THEN IF (TB(3) = 80) THEN
277	        IF (TB(4) = 0) THEN RETURN(1);
278	    RETURN(0);
279	END;
280	
281	IS_REFLECT: PROC RETURNS(INT);
282	    IF (TB(0) = 82) THEN IF (TB(1) = 69) THEN IF (TB(2) = 70) THEN IF (TB(3) = 76) THEN
283	        IF (TB(4) = 69) THEN IF (TB(5) = 67) THEN IF (TB(6) = 84) THEN IF (TB(7) = 0) THEN
284	            RETURN(1);
285	    RETURN(0);
286	END;
287	
288	/* REFLECT_STR -- pronoun-swap a string in place (for ELIZA-style reflection).
289	 * Walks the source word-by-word and writes a new copy into SB with each word
290	 * swapped per the table below. Words are runs of non-space chars. Returns
291	 * the SB offset of the new (null-terminated) string.
292	 *
293	 * Map (case-insensitive in input; output is uppercase):
294	 *   I/ME       -> YOU
295	 *   MY/MINE    -> YOUR / YOURS
296	 *   AM         -> ARE
297	 *   YOU        -> I        (heuristic; cannot disambiguate subj/obj)
298	 *   YOUR       -> MY
299	 *   YOURS      -> MINE
300	 *   ARE        -> AM
301	 *   WAS        -> WERE
302	 *   WERE       -> WAS
303	 *   I'M        -> YOU ARE
304	 *   I'VE       -> YOU HAVE
305	 *   YOU'RE     -> I AM
306	 *   YOU'VE     -> I HAVE
307	 * All other words pass through unchanged.
308	 */
309	REFLECT_STR: PROC(SRCOFF INT) RETURNS(INT);
310	    DCL OFF INT;
311	    DCL SP PTR;
312	    DCL DP PTR;
313	    DCL CH INT;
314	    DCL I INT;
315	    DCL WLEN INT;
316	    DCL WBUF(16) BYTE;
317	    DCL FIRST INT;
318	
319	    OFF = SBPOS;
320	    I = 0;
321	    FIRST = 1;
322	
323	    DO WHILE (1 = 1);
324	        /* Skip spaces */
325	        SP = ADDR(SB) + SRCOFF + I;
326	        CH = SP->DTAG;
327	        DO WHILE (CH = 32);
328	            I = I + 1;
329	            SP = ADDR(SB) + SRCOFF + I;
330	            CH = SP->DTAG;
331	        END;
332	        IF (CH = 0) THEN DO;
333	            DP = ADDR(SB) + SBPOS;
334	            DP->DTAG = 0;
335	            SBPOS = SBPOS + 1;
336	            RETURN(OFF);
337	        END;
338	
339	        /* Collect a word into WBUF (cap 15 chars) */
340	        WLEN = 0;
341	        DO WHILE (CH != 0 AND CH != 32);
342	            IF (WLEN < 15) THEN DO;
343	                WBUF(WLEN) = CH;
344	                WLEN = WLEN + 1;
345	            END;
346	            I = I + 1;
347	            SP = ADDR(SB) + SRCOFF + I;
348	            CH = SP->DTAG;
349	        END;
350	        WBUF(WLEN) = 0;
351	
352	        /* Emit a leading space between words */
353	        IF (FIRST = 0) THEN DO;
354	            DP = ADDR(SB) + SBPOS;
355	            DP->DTAG = 32;
356	            SBPOS = SBPOS + 1;
357	        END;
358	        FIRST = 0;
359	
360	        /* Match WBUF against the swap table; emit either the swap or
361	         * the original word into SB at SBPOS. */
362	        CALL EMIT_REFLECT_WORD(ADDR(WBUF), WLEN);
363	    END;
364	END;
365	
366	/* Helper: write the reflected form of word WP (length WL) into SB. */
367	EMIT_REFLECT_WORD: PROC(WP PTR, WL INT);
368	    DCL C0 INT;
369	    DCL C1 INT;
370	    DCL C2 INT;
371	    DCL C3 INT;
372	    DCL C4 INT;
373	    DCL Q PTR;
374	
375	    Q = WP;
376	    C0 = Q->DTAG;
377	    Q = WP + 1;
378	    C1 = Q->DTAG;
379	    Q = WP + 2;
380	    C2 = Q->DTAG;
381	    Q = WP + 3;
382	    C3 = Q->DTAG;
383	    Q = WP + 4;
384	    C4 = Q->DTAG;
385	
386	    /* I -> YOU */
387	    IF (WL = 1 AND C0 = 73) THEN DO;
388	        CALL PUTS3(89, 79, 85);
389	        RETURN;
390	    END;
391	    /* ME -> YOU */
392	    IF (WL = 2 AND C0 = 77 AND C1 = 69) THEN DO;
393	        CALL PUTS3(89, 79, 85);
394	        RETURN;
395	    END;
396	    /* MY -> YOUR */
397	    IF (WL = 2 AND C0 = 77 AND C1 = 89) THEN DO;
398	        CALL PUTS4(89, 79, 85, 82);
399	        RETURN;
400	    END;
401	    /* MINE -> YOURS */
402	    IF (WL = 4 AND C0 = 77 AND C1 = 73 AND C2 = 78 AND C3 = 69) THEN DO;
403	        CALL PUTS5(89, 79, 85, 82, 83);
404	        RETURN;
405	    END;
406	    /* AM -> ARE */
407	    IF (WL = 2 AND C0 = 65 AND C1 = 77) THEN DO;
408	        CALL PUTS3(65, 82, 69);
409	        RETURN;
410	    END;
411	    /* YOU -> I */
412	    IF (WL = 3 AND C0 = 89 AND C1 = 79 AND C2 = 85) THEN DO;
413	        CALL SBPUT(73);
414	        RETURN;
415	    END;
416	    /* YOUR -> MY */
417	    IF (WL = 4 AND C0 = 89 AND C1 = 79 AND C2 = 85 AND C3 = 82) THEN DO;
418	        CALL PUTS2(77, 89);
419	        RETURN;
420	    END;
421	    /* YOURS -> MINE */
422	    IF (WL = 5 AND C0 = 89 AND C1 = 79 AND C2 = 85 AND C3 = 82 AND C4 = 83) THEN DO;
423	        CALL PUTS4(77, 73, 78, 69);
424	        RETURN;
425	    END;
426	    /* ARE -> AM */
427	    IF (WL = 3 AND C0 = 65 AND C1 = 82 AND C2 = 69) THEN DO;
428	        CALL PUTS2(65, 77);
429	        RETURN;
430	    END;
431	    /* WAS -> WERE */
432	    IF (WL = 3 AND C0 = 87 AND C1 = 65 AND C2 = 83) THEN DO;
433	        CALL PUTS4(87, 69, 82, 69);
434	        RETURN;
435	    END;
436	    /* WERE -> WAS */
437	    IF (WL = 4 AND C0 = 87 AND C1 = 69 AND C2 = 82 AND C3 = 69) THEN DO;
438	        CALL PUTS3(87, 65, 83);
439	        RETURN;
440	    END;
441	    /* Default: pass through unchanged */
442	    DCL K INT;
443	    DCL CP PTR;
444	    DCL CC INT;
445	    K = 0;
446	    DO WHILE (K < WL);
447	        CP = WP + K;
448	        CC = CP->DTAG;
449	        CALL SBPUT(CC);
450	        K = K + 1;
451	    END;
452	END;
453	
454	/* Tiny SB-emit helpers used by EMIT_REFLECT_WORD. */
455	SBPUT: PROC(C INT);
456	    DCL DP PTR;
457	    DP = ADDR(SB) + SBPOS;
458	    DP->DTAG = C;
459	    SBPOS = SBPOS + 1;
460	END;
461	PUTS2: PROC(A INT, B INT);
462	    CALL SBPUT(A);
463	    CALL SBPUT(B);
464	END;
465	PUTS3: PROC(A INT, B INT, C INT);
466	    CALL SBPUT(A);
467	    CALL SBPUT(B);
468	    CALL SBPUT(C);
469	END;
470	PUTS4: PROC(A INT, B INT, C INT, D INT);
471	    CALL SBPUT(A);
472	    CALL SBPUT(B);
473	    CALL SBPUT(C);
474	    CALL SBPUT(D);
475	END;
476	PUTS5: PROC(A INT, B INT, C INT, D INT, E INT);
477	    CALL SBPUT(A);
478	    CALL SBPUT(B);
479	    CALL SBPUT(C);
480	    CALL SBPUT(D);
481	    CALL SBPUT(E);
482	END;
483	
484	SBSAVE: PROC RETURNS(INT);
485	    DCL OFF INT;
486	    DCL I INT;
487	    DCL C INT;
488	    DCL DP PTR;
489	    OFF = SBPOS;
490	    I = 0;
491	    C = TB(0);
492	    DO WHILE (C != 0 AND I < 127);
493	        DP = ADDR(SB) + SBPOS;
494	        DP->DTAG = C;
495	        SBPOS = SBPOS + 1;
496	        I = I + 1;
497	        C = TB(I);
498	    END;
499	    DP = ADDR(SB) + SBPOS;
500	    DP->DTAG = 0;
501	    SBPOS = SBPOS + 1;
502	    RETURN(OFF);
503	END;
504	
505	/* ---- Output ---- */
506	
507	/* Render integer V as decimal characters into SB at SBPOS. */
508	EMIT_DEC: PROC(V INT);
509	    DCL BUF(12) BYTE;
510	    DCL POS INT;
511	    DCL N INT;
512	    DCL D INT;
513	    DCL DP PTR;
514	    N = V;
515	    IF (N = 0) THEN DO;
516	        DP = ADDR(SB) + SBPOS;
517	        DP->DTAG = 48;
518	        SBPOS = SBPOS + 1;
519	        RETURN;
520	    END;
521	    POS = 0;
522	    DO WHILE (N > 0);
523	        D = N;
524	        DO WHILE (D >= 10);
525	            D = D - 10;
526	        END;
527	        BUF(POS) = 48 + D;
528	        POS = POS + 1;
529	        D = 0;
530	        DO WHILE (N >= 10);
531	            N = N - 10;
532	            D = D + 1;
533	        END;
534	        N = D;
535	    END;
536	    DO WHILE (POS > 0);
537	        POS = POS - 1;
538	        DP = ADDR(SB) + SBPOS;
539	        DP->DTAG = BUF(POS);
540	        SBPOS = SBPOS + 1;
541	    END;
542	END;
543	
544	PUT_DEC: PROC(V INT);
545	    DCL BUF(12) BYTE;
546	    DCL POS INT;
547	    DCL N INT;
548	    DCL D INT;
549	    N = V;
550	    IF (N = 0) THEN DO;
551	        CALL UART_PUTCHAR(48);
552	        RETURN;
553	    END;
554	    POS = 0;
555	    DO WHILE (N > 0);
556	        D = N;
557	        DO WHILE (D >= 10);
558	            D = D - 10;
559	        END;
560	        BUF(POS) = 48 + D;
561	        POS = POS + 1;
562	        D = 0;
563	        DO WHILE (N >= 10);
564	            N = N - 10;
565	            D = D + 1;
566	        END;
567	        N = D;
568	    END;
569	    DO WHILE (POS > 0);
570	        POS = POS - 1;
571	        CALL UART_PUTCHAR(BUF(POS));
572	    END;
573	END;
574	
575	/* ---- Special symbol detection (N_OUT/N_INP now in snoglob.msw) ---- */
576	
577	FIND_SPECIAL: PROC;
578	    DCL I INT;
579	    DCL NP PTR;
580	    OUT_SYM = 0 - 1;
581	    INP_SYM = 0 - 1;
582	    RAWINP_SYM = 0 - 1;
583	    I = 0;
584	    DO WHILE (I < SYMC);
585	        NP = ADDR(SYMN) + I * SYM_WIDTH;
586	        IF (SCEQ(NP, ADDR(N_OUT)) != 0) THEN
587	            OUT_SYM = I;
588	        IF (SCEQ(NP, ADDR(N_INP)) != 0) THEN
589	            INP_SYM = I;
590	        IF (SCEQ(NP, ADDR(N_RAWINP)) != 0) THEN
591	            RAWINP_SYM = I;
592	        I = I + 1;
593	    END;
594	END;
595	
596	/* Dummy MAIN for library compilation */
597	MAIN: PROC;
598	END;
