/* PARSE_GOTOS -- parse all goto modifiers attached to statement S.
 *
 * On entry: TT is on the leading TK_COLON.
 * On exit:  TT is past the last goto's `)`. Trailing trash up to EOL
 *           is the caller's problem.
 *
 * Handles all SNOBOL4 goto-syntax variants on a single statement:
 *
 *     :S(L1)            -- success-only
 *     :F(L1)            -- failure-only
 *     :(L1)             -- unconditional
 *     :S(L1):F(L2)      -- combined, both with leading colons
 *     :S(L1) :F(L2)     -- same (whitespace insignificant)
 *     :S(L1)F(L2)       -- second goto without colon prefix
 *     :F(L2):S(L1)      -- reversed order
 *     :(RETURN)         -- procedure return
 *     :(FRETURN)        -- failed return
 *
 * S_GLBL_S / S_GLBL_F carry the success/failure label indices
 * (set to -1 if not specified). UNCOND / RET / FRET use S_GTYP +
 * S_GLBL since they are mutually exclusive with S/F.
 */
PARSE_GOTOS: PROC(S INT);
    DCL G_KIND INT;          /* 0=UNCOND, 1=S, 2=F */
    DCL LBL_IDX INT;
    DCL CONT INT;

    CONT = 1;
    DO WHILE (CONT = 1);
        CONT = 0;

        /* Consume the leading colon (always present on the first
         * iteration; optional on subsequent ones for the no-colon
         * variant `:S(L1)F(L2)`). */
        IF (TT = TK_COLON) THEN CALL LEX;

        /* Optional S/F modifier. Default kind = UNCOND for `:(L)`. */
        G_KIND = 0;
        IF (TT = TK_IDENT) THEN DO;
            IF (TB(0) = 83 AND TB(1) = 0) THEN DO;
                G_KIND = 1;
                CALL LEX;
            END;
            ELSE IF (TB(0) = 70 AND TB(1) = 0) THEN DO;
                G_KIND = 2;
                CALL LEX;
            END;
        END;

        /* Require `(`; if absent, bail (graceful, matches old code). */
        IF (TT != TK_LPAREN) THEN RETURN;
        CALL LEX;

        /* Target: RETURN, FRETURN, or label name. */
        IF (TT = TK_IDENT) THEN DO;
            IF (TB(0) = 82 AND TB(1) = 69 AND TB(2) = 84 AND TB(3) = 85 AND TB(4) = 82 AND TB(5) = 78 AND TB(6) = 0) THEN DO;
                S_GTYP(S) = GT_RET;
                S_GLBL(S) = 0 - 1;
                CALL LEX;
            END;
            ELSE IF (TB(0) = 70 AND TB(1) = 82 AND TB(2) = 69 AND TB(3) = 84 AND TB(4) = 85 AND TB(5) = 82 AND TB(6) = 78 AND TB(7) = 0) THEN DO;
                S_GTYP(S) = GT_FRET;
                S_GLBL(S) = 0 - 1;
                CALL LEX;
            END;
            ELSE DO;
                LBL_IDX = SBSAVE();
                CALL LEX;
                IF (G_KIND = 1) THEN S_GLBL_S(S) = LBL_IDX;
                ELSE IF (G_KIND = 2) THEN S_GLBL_F(S) = LBL_IDX;
                ELSE DO;
                    S_GTYP(S) = GT_UNCOND;
                    S_GLBL(S) = LBL_IDX;
                END;
            END;
        END;

        /* Eat `)`. */
        IF (TT = TK_RPAREN) THEN CALL LEX;

        /* Continue if another goto follows: either `:` (any modifier)
         * or directly `S(...)` / `F(...)` without a colon prefix. */
        IF (TT = TK_COLON) THEN CONT = 1;
        ELSE IF (TT = TK_IDENT) THEN DO;
            IF (TB(0) = 83 AND TB(1) = 0) THEN CONT = 1;
            ELSE IF (TB(0) = 70 AND TB(1) = 0) THEN CONT = 1;
        END;
    END;
END;

