 * exclusive with S/F (the parser enforces this). */
EMIT_GOTO: PROC(S INT);
    IF (S_GLBL_S(S) >= 0) THEN DO;
        CALL AM_EMIT_OP(OP_BR_SUCC);
        S_GOTO_OFF_S(S) = AM_PC;
        CALL AM_EMIT_WORD(0);
    END;
    IF (S_GLBL_F(S) >= 0) THEN DO;
        CALL AM_EMIT_OP(OP_BR_FAIL);
        S_GOTO_OFF_F(S) = AM_PC;
        CALL AM_EMIT_WORD(0);
    END;
    SELECT;
        WHEN (S_GTYP(S) = GT_UNCOND) DO;
            CALL AM_EMIT_OP(OP_BR);
            S_GOTO_OFF(S) = AM_PC;
            CALL AM_EMIT_WORD(0);
        END;
        WHEN (S_GTYP(S) = GT_RET)  CALL AM_EMIT_OP(OP_RET);
        WHEN (S_GTYP(S) = GT_FRET) CALL AM_EMIT_OP(OP_FRET);
    END;
END;

/* Fix up goto targets using label table (no bytecode scanning).
 * Each statement may have up to three patch sites: the unconditional
 * slot (S_GOTO_OFF / S_GLBL), the success slot (S_GOTO_OFF_S /
 * S_GLBL_S), and the failure slot (S_GOTO_OFF_F / S_GLBL_F). */
FIXUP_GOTOS: PROC;
    DCL I INT;
    DCL OFF INT;
    DCL TGT INT;
    I = 0;
    DO WHILE (I < STCNT);
        OFF = S_GOTO_OFF(I);
        IF (OFF >= 0 AND S_GLBL(I) >= 0) THEN DO;
            TGT = LBL_FIND(S_GLBL(I));
            IF (TGT >= 0) THEN
                CALL AM_PATCH_WORD(OFF, STMT_ADDR(TGT));
        END;
        OFF = S_GOTO_OFF_S(I);
        IF (OFF >= 0 AND S_GLBL_S(I) >= 0) THEN DO;
            TGT = LBL_FIND(S_GLBL_S(I));
            IF (TGT >= 0) THEN
                CALL AM_PATCH_WORD(OFF, STMT_ADDR(TGT));
        END;
        OFF = S_GOTO_OFF_F(I);
        IF (OFF >= 0 AND S_GLBL_F(I) >= 0) THEN DO;
            TGT = LBL_FIND(S_GLBL_F(I));
            IF (TGT >= 0) THEN
                CALL AM_PATCH_WORD(OFF, STMT_ADDR(TGT));
        END;
        I = I + 1;
    END;
END;

