/* Emit goto branch(es) for a statement. Combined :S(L1):F(L2) on a
 * predicate-bearing statement emits OP_BR_SUCC immediately followed
 * by OP_BR_FAIL; the second branch is patched via S_GOTO_OFF_F. */
EMIT_GOTO: PROC(S INT);
    SELECT;
        WHEN (S_GTYP(S) = GT_UNCOND) DO;
            CALL AM_EMIT_OP(OP_BR);
            S_GOTO_OFF(S) = AM_PC;
            CALL AM_EMIT_WORD(0);
        END;
        WHEN (S_GTYP(S) = GT_SUCC) DO;
            CALL AM_EMIT_OP(OP_BR_SUCC);
            S_GOTO_OFF(S) = AM_PC;
            CALL AM_EMIT_WORD(0);
            IF (S_GLBL_F(S) >= 0) THEN DO;
                CALL AM_EMIT_OP(OP_BR_FAIL);
                S_GOTO_OFF_F(S) = AM_PC;
                CALL AM_EMIT_WORD(0);
            END;
        END;
        WHEN (S_GTYP(S) = GT_FAIL) DO;
            CALL AM_EMIT_OP(OP_BR_FAIL);
            S_GOTO_OFF(S) = AM_PC;
            CALL AM_EMIT_WORD(0);
        END;
        WHEN (S_GTYP(S) = GT_RET)  CALL AM_EMIT_OP(OP_RET);
        WHEN (S_GTYP(S) = GT_FRET) CALL AM_EMIT_OP(OP_FRET);
    END;
END;

