input.new_string:
/* Collect expression parts. TK_LPAREN at primary
 * position is consumed silently and the loop
 * continues -- after the inner expression parses its
 * slots, the trailing close-paren consume at the end
 * of each iteration eats the matching `)`. Single-
 * level parens around any primary or binop work; the
 * existing multi-op limitation (only one S_OEOP per
 * statement) is unchanged regardless of parens. */
DO WHILE (TT = TK_INT OR TT = TK_STR OR TT = TK_IDENT OR TT = TK_LPAREN);
    IF (TT = TK_LPAREN) THEN DO;
        /* Consume `(` and re-enter the loop -- the
         * inner expression's slots accumulate into
         * the same EP slot stream. */
        CALL LEX;
    END;
    ELSE IF (TT = TK_INT) THEN DO;
        IF (EPI < EPSLOTS) THEN DO;
            EP_TYP(EPB + EPI) = OE_INT;
            EP_VAL(EPB + EPI) = TV;
            EPI = EPI + 1;
        END;
        CALL LEX;
    END;
    ELSE IF (TT = TK_STR) THEN DO;

